import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A job is attempted at most this many times in total before it is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
export const RETRY_DELAY_MS = 500;
export const TRANSIENT_ERROR = 'transient failure';

/** Raw row as stored in SQLite. */
export interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  status: JobStatus;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

/** Job as returned by the HTTP API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey?: string;
}

export type SubmitOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

type Params = Array<string | number | null>;

function run(db: DatabaseSync, sql: string, params: Params = []): void {
  db.prepare(sql).run(...params);
}

function get(db: DatabaseSync, sql: string, params: Params = []): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

function getAll(db: DatabaseSync, sql: string, params: Params = []): JobRow[] {
  return db.prepare(sql).all(...params) as unknown as JobRow[];
}

/** Runs `fn` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return get(db, 'SELECT * FROM jobs WHERE id = ?', [id]);
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): JobRow[] {
  return getAll(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

/**
 * Creates a job, or resolves an idempotent submission. The key lookup and insert share one
 * transaction, so a key can never create two jobs.
 */
export function submitJob(db: DatabaseSync, job: NewJob): SubmitOutcome {
  return transaction<SubmitOutcome>(db, () => {
    if (job.idempotencyKey !== undefined) {
      const existing = get(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', [job.idempotencyKey]);
      if (existing) {
        const samePayload =
          existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
        return samePayload ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    const now = new Date();
    const id = randomUUID();
    run(
      db,
      `INSERT INTO jobs (id, idempotency_key, input, steps, fail_attempts, attempts, status, progress_completed, next_run_at, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 0, 'queued', 0, ?, ?, ?)`,
      [id, job.idempotencyKey ?? null, job.input, job.steps, job.failAttempts, now.getTime(), now.toISOString(), now.toISOString()],
    );
    const row = getJobRow(db, id);
    if (!row) throw new Error(`job ${id} missing after insert`);
    return { kind: 'created', row };
  });
}

/** Takes the oldest queued job that is due, marks it running and starts a new attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return transaction(db, () => {
    const next = get(db, "SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1", [nowMs]);
    if (!next) return undefined;
    run(
      db,
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?",
      [new Date().toISOString(), next.id],
    );
    return getJobRow(db, next.id);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  run(db, 'UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?', [completed, new Date().toISOString(), id]);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  run(
    db,
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE id = ?",
    [output, new Date().toISOString(), id],
  );
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  run(
    db,
    "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, progress_completed = 0, updated_at = ? WHERE id = ?",
    [error, new Date().toISOString(), id],
  );
}

/** Returns a job to the queue to be retried once `nextRunAt` (epoch ms) has passed. */
export function requeueJob(db: DatabaseSync, id: string, nextRunAt: number): void {
  run(
    db,
    "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?",
    [nextRunAt, new Date().toISOString(), id],
  );
}

/** Jobs left `running` by a worker that stopped are queued again so they are processed again. */
export function requeueInterrupted(db: DatabaseSync): number {
  return transaction(db, () => {
    const result = db
      .prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE status = 'running'")
      .run(new Date().toISOString());
    return Number(result.changes);
  });
}

export function recordHeartbeat(db: DatabaseSync, name = 'worker'): void {
  run(db, 'INSERT OR REPLACE INTO heartbeats (name, updated_at_ms) VALUES (?, ?)', [name, Date.now()]);
}

export function clearHeartbeat(db: DatabaseSync, name = 'worker'): void {
  run(db, 'DELETE FROM heartbeats WHERE name = ?', [name]);
}

/** Epoch ms of the last heartbeat, or undefined if none has been recorded. */
export function lastHeartbeat(db: DatabaseSync, name = 'worker'): number | undefined {
  const row = db.prepare('SELECT updated_at_ms FROM heartbeats WHERE name = ?').get(name) as
    | { updated_at_ms: number }
    | undefined;
  return row?.updated_at_ms;
}

