import type { NewJob } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type Validated = { ok: true; job: NewJob } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

export function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  return (value.split(';')[0] ?? '').trim().toLowerCase() === 'application/json';
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function checkInteger(value: unknown, min: number, max: number, field: string, fields: FieldError[]): void {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field, message: 'Must be an integer.' });
  } else if (value < min || value > max) {
    fields.push({ field, message: `Must be an integer from ${min} to ${max}.` });
  }
}

export function validateSubmission(req: {
  contentType: string | undefined;
  body: string;
  bodyTooLarge: boolean;
  idempotencyKey: string | undefined;
}): Validated {
  const bodyError = (message: string): Validated => ({ ok: false, fields: [{ field: 'body', message }] });

  if (!isJsonContentType(req.contentType)) return bodyError('Content-Type must be application/json.');
  if (req.bodyTooLarge) return bodyError('Request body is too large.');

  let parsed: unknown;
  try {
    parsed = JSON.parse(req.body);
  } catch {
    return bodyError('Body must be valid JSON.');
  }
  if (!isPlainObject(parsed)) return bodyError('Body must be a JSON object.');

  const fields: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps, failAttempts } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'Required string.' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }

  if (steps !== undefined) checkInteger(steps, 1, 20, 'steps', fields);
  if (failAttempts !== undefined) checkInteger(failAttempts, 0, 5, 'failAttempts', fields);

  if (req.idempotencyKey !== undefined && !IDEMPOTENCY_KEY.test(req.idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return {
    ok: true,
    job: {
      input: input as string,
      steps: steps === undefined ? DEFAULT_STEPS : (steps as number),
      failAttempts: failAttempts === undefined ? DEFAULT_FAIL_ATTEMPTS : (failAttempts as number),
      idempotencyKey: req.idempotencyKey,
    },
  };
}

