import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  MAX_ATTEMPTS,
  RETRY_DELAY_MS,
  TRANSIENT_ERROR,
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  recordHeartbeat,
  requeueInterrupted,
  requeueJob,
  setProgress,
  type JobRow,
} from './jobs.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
const abort = new AbortController();
const { signal } = abort;

/** Waits for `ms`, or returns early when shutdown starts. Never rejects. */
function pause(ms: number): Promise<void> {
  return sleep(ms, undefined, { signal }).then(
    () => undefined,
    () => undefined,
  );
}

/** Runs one attempt of a claimed job. The job is already `running` with `attempts` incremented. */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    if (job.attempts >= MAX_ATTEMPTS) {
      failJob(db, job.id, TRANSIENT_ERROR);
      console.log(`job ${job.id} failed after ${job.attempts} attempts`);
    } else {
      requeueJob(db, job.id, Date.now() + RETRY_DELAY_MS);
      console.log(`job ${job.id} attempt ${job.attempts} failed; retrying`);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await pause(STEP_MS);
    if (signal.aborted) return; // left `running`; shutdown requeues it
    setProgress(db, job.id, step);
  }
  completeJob(db, job.id, job.input.toUpperCase());
  console.log(`job ${job.id} completed`);
}

// A worker that stopped mid-attempt left jobs `running`; process them again.
const recovered = requeueInterrupted(db);
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);

recordHeartbeat(db);
const heartbeat = setInterval(() => recordHeartbeat(db), HEARTBEAT_MS);

function stop(): void {
  if (signal.aborted) return;
  console.log('worker stopping');
  abort.abort();
}
process.on('SIGTERM', stop);
process.on('SIGINT', stop);

console.log('worker started');
while (!signal.aborted) {
  const job = claimNextJob(db, Date.now());
  if (!job) {
    await pause(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeat);
requeueInterrupted(db);
clearHeartbeat(db);
db.close();
console.log('worker stopped');

